#!/usr/bin/env bash
# Native regeneration of every example package from its own input: `kcore gen` on
# examples/NAME/NS/definition.kore with the options examples/run.sh gives it, into
# .lake/regen/NAME (ignored), compared with the committed package by
# `diff -r -I 'Generated by .kcore gen'` (the header names the input path), leaving out the user's
# modules (User), the build (.lake), the lake files, and the directories of a package that are input
# written by hand, which `kcore gen` does not write: `claims` (ref-kimp's K claims in the KORE that
# kprove writes, from which k2lean writes User's statement; test/pins-kimp.sh reads them).
# One line per package: `identical`, or what differs. Each `kcore gen` under a 12 GiB memory scope
# (gen/gen.sh); JOBS at once.
# Usage: test/regen.sh [-j JOBS] [NAME...]   (from anywhere; `kcore` built first)
# Exit 1 when a package differs or fails to generate.
set -u
K=$(cd "$(dirname "$0")/.." && pwd); cd "$K"
jobs=1; [ "${1:-}" = -j ] && { jobs=$2; shift 2; }
# name|namespace|options (as examples/run.sh)
all=(
"peano|Peano|--tie --cert term=examples/runs/peano-term.cert.json"
"prio|Prio|--wf --cert goD=examples/runs/prio-goD.cert.json --cert goB=examples/runs/prio-goB.cert.json"
"kink-imp|KinkImp|--wf"
"kimp|Kimp|--wf --keyed env"
"imp-sec|ImpSec|--wf"
"imp-sec-leaky|ImpSecLeaky|--wf"
"ph|Ph|--wf"
"kryp|Kryp|--wf"
"vault|Vault|--wf --high sec"
"vault-leaky|VaultLeaky|--wf --high sec"
"colls-list|CollsList|--wf"
"lazy|Lazy|--wf"
"fprio|Fprio|--wf"
"colls|Colls|--wf"
"ref-peano|RefPeano|--wf"
"ref-fprio|RefFprio|--wf"
"ref-kimp|RefKimp|--wf"
"ref-kk|RefKk|--core"
)
want=" $* "
O=.lake/regen; mkdir -p "$O"
one() {
  IFS='|' read -r name ns opts <<< "$1"
  t0=$(date +%s); rm -rf "$O/$name"
  gen/gen.sh "examples/$name/$ns/definition.kore" "$O/$name" "$ns" $opts > "$O/$name.log" 2>&1; rc=$?
  t=$(( $(date +%s) - t0 ))
  if [ $rc -ne 0 ]; then echo "$name: gen failed (exit $rc, $t s; $O/$name.log)"; return; fi
  d=$(diff -rq -I 'Generated by .kcore gen' -x User -x .lake -x lakefile.toml -x lake-manifest.json \
      -x lean-toolchain -x claims "$O/$name" "examples/$name" 2>&1)
  if [ -z "$d" ]; then echo "$name: identical ($t s)"
  else echo "$name: differs ($t s): $(echo "$d" | wc -l) files: $(echo "$d" | head -3 | tr '\n' ';')"; fi
}
res=$O/results.txt; : > "$res"
for e in "${all[@]}"; do
  [ "$want" = "  " ] || case "$want" in *" ${e%%|*} "*) ;; *) continue;; esac
  while [ "$(jobs -rp | wc -l)" -ge "$jobs" ]; do wait -n; done
  one "$e" >> "$res" &
done
wait
sort "$res"
n=$(grep -c . "$res"); ok=$(grep -c ': identical' "$res")
echo "regenerated: $ok of $n identical"
[ "$ok" = "$n" ]
